//! Unmanaged `.github` enumeration and allowlist checks.

use std::fs;

use tempfile::TempDir;
use velnor_actions_contract::{GithubConfig, UnmanagedPolicy};

type TestResult = Result<(), Box<dyn std::error::Error>>;

const MARKER: &str =
    "# Generated by Velnor Actions 0.1.0; edit .velnor/config.toml and regenerate.\n";

fn write(root: &std::path::Path, relative: &str, text: &str) -> TestResult {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, text)?;
    Ok(())
}

fn config(allow: &[&str]) -> GithubConfig {
    GithubConfig {
        unmanaged: UnmanagedPolicy::Deny,
        allow: allow.iter().map(|entry| (*entry).to_owned()).collect(),
    }
}

#[test]
fn lists_only_entries_generation_would_preserve() -> TestResult {
    let root = TempDir::new()?;
    write(root.path(), ".github/CODEOWNERS", "* @owner\n")?;
    write(root.path(), ".github/ISSUE_TEMPLATE/bug.yml", "x\n")?;
    write(root.path(), ".github/workflows/ci.yml", "retired\n")?;
    write(root.path(), ".github/workflows/hand.yml", "kept\n")?;
    write(root.path(), ".github/AGENTS.md", "declared format\n")?;
    write(
        root.path(),
        ".github/actions/u26/action.yml",
        &format!("{MARKER}x\n"),
    )?;
    write(root.path(), ".github/actions/hand/action.yml", "unmarked\n")?;
    write(
        root.path(),
        ".github/scripts/gen.sh",
        &format!("{MARKER}x\n"),
    )?;
    write(root.path(), ".github/scripts/own.sh", "#!/bin/sh\n")?;
    write(root.path(), ".github/dco.yml", &format!("{MARKER}x\n"))?;
    fs::create_dir_all(root.path().join(".github/empty"))?;
    let entries = super::list(root.path(), &[], &config(&[]))?;
    assert_eq!(
        entries,
        [
            ".github/CODEOWNERS",
            ".github/ISSUE_TEMPLATE/bug.yml",
            ".github/actions/hand/action.yml",
            ".github/empty",
            ".github/scripts/own.sh",
        ]
    );
    Ok(())
}

#[test]
fn preserved_workflows_and_allowlist_are_exempt() -> TestResult {
    let root = TempDir::new()?;
    write(root.path(), ".github/CODEOWNERS", "* @owner\n")?;
    write(root.path(), ".github/ISSUE_TEMPLATE/bug.yml", "x\n")?;
    write(root.path(), ".github/FUNDING.yml", "x\n")?;
    write(root.path(), ".github/workflows/hand.yml", "kept\n")?;
    let preserved = [".github/workflows/hand.yml".to_owned()];
    let entries = super::list(
        root.path(),
        &preserved,
        &config(&[".github/CODEOWNERS", ".github/ISSUE_TEMPLATE"]),
    )?;
    assert_eq!(entries, [".github/FUNDING.yml"]);
    Ok(())
}

#[test]
fn generated_cache_cleanup_workflow_is_not_reported_as_unmanaged() -> TestResult {
    let root = TempDir::new()?;
    write(
        root.path(),
        ".github/workflows/cache-cleanup.yml",
        &format!("{MARKER}name: cleanup\n"),
    )?;
    write(root.path(), ".github/workflows/hand.yml", "name: hand\n")?;
    let preserved = [".github/workflows/hand.yml".to_owned()];
    assert_eq!(
        super::list(root.path(), &preserved, &config(&[]))?,
        Vec::<String>::new(),
        "The list must exclude generated cleanup and explicitly preserved workflows."
    );
    Ok(())
}

#[test]
fn absent_github_is_empty_and_symlinked_github_is_refused() -> TestResult {
    let root = TempDir::new()?;
    let none: Vec<String> = Vec::new();
    assert_eq!(super::list(root.path(), &[], &config(&[]))?, none);
    let elsewhere = TempDir::new()?;
    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(elsewhere.path(), root.path().join(".github"))?;
        assert!(super::list(root.path(), &[], &config(&[])).is_err());
    }
    Ok(())
}

#[cfg(unix)]
#[test]
fn symlinks_are_reported_without_following() -> TestResult {
    let root = TempDir::new()?;
    fs::create_dir_all(root.path().join(".github"))?;
    std::os::unix::fs::symlink("nowhere", root.path().join(".github/link"))?;
    assert_eq!(
        super::list(root.path(), &[], &config(&[]))?,
        [".github/link"]
    );
    Ok(())
}
